{
  "summary": "Intellectual property created by ISA remains ISA's sole property, while Rubicon's offerings and IP remain Rubicon's sole property. Works created by Rubicon generally belong exclusively to ISA as works for hire.",
  "evidence": [
    {
      "passage_id": 1,
      "quote": "all right, title and interest in and to Intellectual Property which is created by or provided by ISA... are and shall be and shall remain the sole property of ISA."
    },
    {
      "passage_id": 4,
      "quote": "all right, title and interest in and to the Rubicon Offerings and, subject to the provisions of Section 5.2, any other Intellectual Property of Rubicon... are and shall be the sole property of Rubicon."
    },
    {
      "passage_id": 5,
      "quote": "To the extent copyrightable, all Works shall be deemed to be \"works for hire\" and ISA shall be deemed to be the author thereof under the U.S. Copyright Act."
    }
  ]
}
